<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class Member extends Model { protected $fillable=['membership_number','first_name','last_name','email','phone','address','membership_category_id','membership_level_id','status','joined_at','expires_at']; protected function casts(): array { return ['email_verified_at'=>'datetime','joined_at'=>'date','expires_at'=>'date']; } public function category(): BelongsTo { return $this->belongsTo(MembershipCategory::class,'membership_category_id'); } public function level(): BelongsTo { return $this->belongsTo(MembershipLevel::class,'membership_level_id'); } public function transactions(): HasMany { return $this->hasMany(MembershipTransaction::class); } public function getNameAttribute(): string { return trim($this->first_name.' '.$this->last_name); } }
